//! A signal applies to the lanes whose traffic runs the way its
//! `orientation` names, not to a side of the road.
//!
//! `tests/data/signal_direction.xodr` is generated by `signal_direction.py`.
//! Its lanes 2 and -2 are reversed, -3 runs both ways, and road 2 drives on
//! the left, so no side of a road holds one direction.

use xodr::{load_file_with_provenance, Provenance, RoadNetwork};

fn fixture() -> (RoadNetwork, Provenance) {
    load_file_with_provenance("tests/data/signal_direction.xodr").unwrap()
}

/// `(road, lane id)` of each lane signal `od_id` on `road` applies to,
/// sorted.
fn applies_to(net: &RoadNetwork, prov: &Provenance, signal: &str) -> Vec<(String, i32)> {
    let placed = prov
        .signals
        .iter()
        .find(|p| p.od_id == signal)
        .unwrap_or_else(|| panic!("no signal {signal}"));
    let mut found: Vec<_> = net.signals()[placed.signal.0]
        .lanes
        .iter()
        .map(|lane| {
            let p = prov.lanes.iter().find(|p| p.lane == *lane).unwrap();
            (p.road_id.clone(), p.od_id)
        })
        .collect();
    found.sort();
    found
}

fn on(road: &str, ids: &[i32]) -> Vec<(String, i32)> {
    let mut found: Vec<_> = ids.iter().map(|&i| (road.to_string(), i)).collect();
    found.sort();
    found
}

#[test]
fn a_plus_signal_applies_to_the_lanes_running_with_s_and_a_minus_signal_to_those_against_it() {
    let (net, prov) = fixture();
    assert_eq!(applies_to(&net, &prov, "1+"), on("1", &[2, -1, -3]));
    assert_eq!(applies_to(&net, &prov, "1-"), on("1", &[1, -2, -3]));
}

#[test]
fn a_none_signal_applies_to_every_lane() {
    let (net, prov) = fixture();
    assert_eq!(applies_to(&net, &prov, "10"), on("1", &[1, 2, -1, -2, -3]));
    assert_eq!(applies_to(&net, &prov, "20"), on("2", &[1, 2, -1, -2, -3]));
    assert_eq!(applies_to(&net, &prov, "30"), on("3", &[1, -1, -2]));
}

#[test]
fn left_hand_traffic_swaps_the_sides() {
    let (net, prov) = fixture();
    assert_eq!(applies_to(&net, &prov, "2+"), on("2", &[1, -2, -3]));
    assert_eq!(applies_to(&net, &prov, "2-"), on("2", &[2, -1, -3]));
}

#[test]
fn a_bidirectional_lane_with_no_direction_runs_both_ways() {
    let (net, prov) = fixture();
    assert_eq!(applies_to(&net, &prov, "3+"), on("3", &[-1, -2]));
    assert_eq!(applies_to(&net, &prov, "3-"), on("3", &[1, -2]));
}

#[test]
fn a_validity_picks_its_lanes_whatever_way_they_run() {
    let (net, prov) = fixture();
    for road in ["1", "2", "3"] {
        assert_eq!(
            applies_to(&net, &prov, &format!("{road}v")),
            on(road, &[-2]),
            "road {road}"
        );
    }
}

#[test]
fn a_reference_picks_its_lanes_by_its_own_orientation_on_its_own_road() {
    let (net, prov) = fixture();
    // The signal itself is `+` on road 1, where lanes 2, -1 and -3 run with
    // +s. Its reference is `-` on road 2, which drives on the left.
    let mut want = on("1", &[2, -1, -3]);
    want.extend(on("2", &[2, -1, -3]));
    want.sort();
    assert_eq!(applies_to(&net, &prov, "ref"), want);
}
